import { test } from 'node:test';
import assert from 'node:assert/strict';
import { findPaymentsForOrder, uncapturedTotalCents } from '../src/services/payment-service.js';
import { PaymentRepository } from '../src/repositories/payment-repository.js';

test('findPaymentsForOrder finds the payment for an order', (t, done) => {
  findPaymentsForOrder(10, (err, rows) => {
    assert.equal(err, null);
    assert.equal(rows.length, 1);
    assert.equal(rows[0].amount_cents, 4200);
    done();
  });
});

test('findPaymentsForOrder passes repository errors to the callback', (t, done) => {
  const boom = new Error('boom');
  t.mock.method(PaymentRepository.prototype, 'findByOrder', () => Promise.reject(boom));
  findPaymentsForOrder(10, (err, rows) => {
    assert.equal(err, boom);
    assert.equal(rows, undefined);
    done();
  });
});

test('uncapturedTotalCents sums uncaptured payments', (t, done) => {
  uncapturedTotalCents((err, total) => {
    assert.equal(err, null);
    assert.equal(total, 9900);
    done();
  });
});

test('uncapturedTotalCents passes repository errors to the callback', (t, done) => {
  const boom = new Error('boom');
  t.mock.method(PaymentRepository.prototype, 'findUncaptured', () => Promise.reject(boom));
  uncapturedTotalCents((err, total) => {
    assert.equal(err, boom);
    assert.equal(total, undefined);
    done();
  });
});

